CREATE TABLE public.website_inquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL, phone text, industry text NOT NULL, message text NOT NULL, kind text NOT NULL DEFAULT 'contact', crm text, consent boolean NOT NULL DEFAULT false, delivery_status text NOT NULL DEFAULT 'pending_sender_setup', request_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.website_inquiries TO service_role; ALTER TABLE public.website_inquiries ENABLE ROW LEVEL SECURITY; CREATE INDEX website_inquiries_rate_limit ON public.website_inquiries (request_hash, created_at); CREATE FUNCTION public.website_inquiries_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$; CREATE TRIGGER website_inquiries_updated_at BEFORE UPDATE ON public.website_inquiries FOR EACH ROW EXECUTE FUNCTION public.website_inquiries_updated_at();